import type { MessageGroup } from "../../../lib/chat/chat-types.ts";
import { resolveMessageVisibleContent } from "../../../lib/chat/message-visibility.ts";
import { resolveAssistantReplyPhase } from "../chat-assistant-reply.ts";
import type { SystemEventRenderItem } from "../chat-system-event-grouping.ts";
import { persistedMessageEntryId } from "../chat-thread-items.ts";
import { isSessionActivityGroup } from "../chat-turn-boundary.ts";
import { prepareChatStreamRender } from "./chat-message-markdown-view.tsx";

type ChatPositionMarker = {
  id: string;
  role: "user" | "assistant";
  anchorId: string;
  message: unknown;
};

export type ChatPositionIndex = Readonly<{
  markers: readonly Readonly<ChatPositionMarker>[];
  markerIdsByMessageId: ReadonlyMap<string, string>;
  /** A mounted preview reads current text without invalidating marker membership. */
  resolveLiveMessage?: (message: unknown) => unknown;
}>;

type RenderItem = SystemEventRenderItem;

export function isVisibleChatStream(part: Parameters<typeof prepareChatStreamRender>[0]): boolean {
  const prepared = prepareChatStreamRender(part);
  return (
    resolveMessageVisibleContent(prepared.message, prepared.normalizedMessage) === "non-text" ||
    Boolean(prepared.displayMarkdown.trim())
  );
}

export function projectChatPositions(
  items: Iterable<RenderItem>,
  expandedWork: ReadonlyMap<string, boolean>,
  messageRowKeysById: Map<string, string>,
  searchActive = false,
): ChatPositionIndex {
  const markers = new Map<string, ChatPositionMarker>();
  const markerIdsByMessageId = new Map<string, string>();
  const add = (
    id: string,
    role: ChatPositionMarker["role"],
    messageId: string,
    message: unknown,
    rowKey: string,
  ) => {
    const marker = markers.get(id);
    if (marker) {
      // Inline commentary must not replace a delivered answer in the position rail.
      if (
        role !== "assistant" ||
        resolveAssistantReplyPhase(message) !== "commentary" ||
        resolveAssistantReplyPhase(marker.message) !== "final_answer"
      ) {
        marker.message = message;
      }
    } else {
      markers.set(id, { id, role, anchorId: messageId, message });
    }
    markerIdsByMessageId.set(messageId, id);
    if (!messageRowKeysById.has(messageId)) {
      messageRowKeysById.set(messageId, rowKey);
    }
  };
  const group = (item: MessageGroup, rowKey: string) => {
    if (
      isSessionActivityGroup(item) &&
      !searchActive &&
      !expandedWork.get("session-activity:" + item.key)
    ) {
      return;
    }
    if ((item.role !== "user" && item.role !== "assistant") || item.visibleContent === "none") {
      return;
    }
    for (const source of item.messages) {
      if (!source.hasVisibleContent) {
        continue;
      }
      const messageId = persistedMessageEntryId(source.message) ?? source.key;
      // A run can span frames, search matches, or a history page missing its user boundary.
      // Without run identity, retain the transcript's existing group boundary.
      const markerId =
        item.role === "user"
          ? messageId
          : item.runId
            ? `run:${item.runId}`
            : (persistedMessageEntryId(item.messages[0]?.message) ?? item.key);
      add(markerId, item.role, messageId, source.message, rowKey);
    }
  };
  const visit = (item: RenderItem, rowKey: string) => {
    if (item.kind === "group") {
      group(item, rowKey);
    } else if (item.kind === "agent-run-frame") {
      for (const part of item.parts) {
        visit(part, rowKey);
      }
    } else if (item.kind === "activity-run") {
      for (const part of item.groups) {
        group(part, rowKey);
      }
    } else if (item.kind === "work-group" && expandedWork.get(item.key)) {
      // Folded work has no mounted bubble to reveal. Its visible final reply owns the anchor.
      for (const part of item.groups) {
        group(part, rowKey === item.key ? `${item.key}:${part.key}` : rowKey);
      }
    } else if (item.kind === "stream-run") {
      for (const part of item.parts) {
        if (part.kind !== "stream") {
          continue;
        }
        if (!isVisibleChatStream(part)) {
          continue;
        }
        add(
          item.runId ? `run:${item.runId}` : item.key,
          "assistant",
          part.key,
          prepareChatStreamRender(part).message,
          rowKey,
        );
      }
    }
  };
  for (const item of items) {
    visit(item, item.key);
  }
  // Transcript order includes continuations after an intervening user steer.
  return { markers: [...markers.values()], markerIdsByMessageId };
}
