import type { JSX } from "@solidjs/web";
import { createSignal, Errored, For, lazy, Loading, Show, onSettled } from "solid-js";
import type { MessageReactionSummary } from "../../../../../packages/gateway-protocol/src/index.js";
import { isReactionEmoji } from "../../../../../packages/gateway-protocol/src/reaction-emoji.js";
import { Icon } from "../../../components/solid/icon.tsx";
import { LazyViewError } from "../../../components/solid/lazy-view-error.tsx";
import { LoadingState } from "../../../components/solid/loading-state.tsx";
import { Popover, type PopoverHandle } from "../../../components/solid/popover.tsx";
import { StrokeIcon } from "../../../components/solid/stroke-icon.tsx";
import { registerChatSessionEnglish } from "../../../i18n/locales/en-chat-session.ts";
import { registerEnglishCatalog, t } from "../../../lib/reactive/i18n.ts";
import { listen } from "../../../lib/reactive/listener.ts";
import "./chat-message-reactions.css";
import type { MessageReactionPlacement } from "./chat-message-reaction-model.ts";

registerEnglishCatalog(registerChatSessionEnglish);

const EmojiSearchPanel = lazy(() => import("../../../components/emoji-search-panel.tsx"), {
  export: "EmojiSearchPanel",
});

const QUICK_REACTIONS = ["👍", "❤️", "🎉", "👀", "🚀", "😂"] as const;
// Shown before the search has a query; quick reactions lead so the grid extends the palette.
const SEARCH_DEFAULTS = [
  ...QUICK_REACTIONS,
  "👎",
  "🙏",
  "🔥",
  "✅",
  "❌",
  "💯",
  "🤔",
  "😮",
  "😢",
  "👏",
  "🙌",
  "💡",
  "🐛",
  "🦞",
  "⚠️",
  "🤝",
  "✨",
  "🎯",
] as const;
let nextPickerId = 0;

export function MessageReactionPicker(props: {
  onSelect?: (emoji: string, remove: boolean) => void;
  activeEmoji: ReadonlySet<string>;
  placement: MessageReactionPlacement;
  class?: string;
  /** A message's reaction summary: it replaces the add icon as this picker's trigger. */
  summary?: JSX.Element;
  /** The summary's accessible name, and the hover content naming who reacted. */
  summaryLabel?: string;
  summaryDetails?: JSX.Element;
  /** Existing reactions lead the palette, so any of them toggles in place. */
  reactions?: readonly MessageReactionSummary[];
  disabled?: boolean;
}) {
  let host!: HTMLElement;
  const [activated, setActivated] = createSignal(false);
  const [custom, setCustom] = createSignal(false);
  const [query, setQuery] = createSignal("");
  // Popovers now share the document's ID namespace instead of individual shadow roots.
  const triggerId = `reaction-trigger-${++nextPickerId}`;
  let popover: PopoverHandle | undefined;
  let trigger!: HTMLButtonElement;
  let searchInput: HTMLInputElement | undefined;
  let backButton: HTMLButtonElement | undefined;
  const paletteButtons: HTMLButtonElement[] = [];
  const stop: (() => void)[] = [];
  const focusPicker = () => {
    if (!popover?.overlay.open) {
      return;
    }
    if (props.disabled) {
      popover.overlay.surface.focus();
      return;
    }
    (custom()
      ? searchInput?.isConnected
        ? searchInput
        : backButton
      : (paletteButtons.find((button) => button.getAttribute("aria-pressed") === "true") ??
        paletteButtons[0])
    )?.focus();
  };
  onSettled(() => () => stop.forEach((dispose) => dispose()));
  const close = () => popover?.overlay.request(false, "return");
  const select = (emoji: string) => {
    if (props.disabled) {
      return;
    }
    props.onSelect?.(emoji, props.activeEmoji.has(emoji));
    close();
  };
  const search = (text: string) => {
    setQuery(text);
    // A pasted or OS-picker emoji applies at once, including ones the shortcode catalog lacks.
    const candidate = text.trim();
    if (isReactionEmoji(candidate)) {
      select(candidate);
    }
  };
  const reset = () => {
    setCustom(false);
    setQuery("");
  };
  const showPalette = () => {
    reset();
    onSettled(focusPicker);
  };
  const showCustom = () => {
    setCustom(true);
    onSettled(focusPicker);
  };
  const back = () => (
    <button
      ref={(button) => {
        backButton = button;
      }}
      class="back"
      type="button"
      aria-label={t("chat.reactions.back")}
      onClick={showPalette}
    >
      <Icon name="arrowLeft" />
    </button>
  );
  const movePaletteFocus = (event: KeyboardEvent) => {
    const buttons = paletteButtons;
    const current = buttons.findIndex((button) => button === host.ownerDocument.activeElement);
    const target =
      event.key === "ArrowRight"
        ? (current + 1) % buttons.length
        : event.key === "ArrowLeft"
          ? (current - 1 + buttons.length) % buttons.length
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? buttons.length - 1
              : -1;
    if (target >= 0) {
      event.preventDefault();
      buttons[target]?.focus();
    }
  };
  return (
    <openclaw-message-reaction-picker ref={(element) => (host = element)} class={props.class}>
      <openclaw-tooltip prop:content={props.summary ? "" : t("chat.reactions.add")}>
        <button
          ref={(element) => {
            trigger = element;
          }}
          id={triggerId}
          class={["trigger", { "chat-reaction-tab": Boolean(props.summary) }]}
          type="button"
          disabled={props.disabled && !props.summary}
          aria-label={props.summaryLabel ?? t("chat.reactions.add")}
          aria-haspopup="dialog"
          aria-expanded="false"
          onClick={() => {
            if (popover) {
              popover.overlay.request(!popover.overlay.open);
            } else {
              setActivated(true);
            }
          }}
        >
          <Show
            when={props.summary}
            fallback={
              <StrokeIcon aria-hidden="true">
                <path d="M21 11.5a9 9 0 1 1-8.5-8.5" />
                <path d="M8 14s1.5 2 4 2 4-2 4-2M16 5h6M19 2v6" />
                <path d="M9 9h.01M15 9h.01" />
              </StrokeIcon>
            }
          >
            {props.summary}
          </Show>
        </button>
        <Show when={props.summaryDetails}>
          <div slot="content">{props.summaryDetails}</div>
        </Show>
      </openclaw-tooltip>
      <Show when={activated()}>
        <Popover
          lazy="while-open"
          sameRoot
          id={`${triggerId}-popover`}
          ref={(handle) => {
            popover = handle;
            stop.push(
              listen(handle.overlay.surface, "overlay-after-show", focusPicker),
              listen(handle.overlay.surface, "overlay-after-hide", reset),
            );
            handle.show();
          }}
          anchor={trigger}
          class={["chat-reaction-picker", { custom: custom() }]}
          placement={props.placement}
          label={t(props.disabled ? "chat.reactions.current" : "chat.reactions.add")}
        >
          <Show when={(props.disabled || !custom()) && props.reactions?.length}>
            <div class="current" role="group" aria-label={t("chat.reactions.current")}>
              <For each={props.reactions} keyed={(reaction) => reaction.emoji}>
                {(reaction) => (
                  <button
                    class="chat-reaction-chip"
                    disabled={props.disabled}
                    type="button"
                    aria-label={`${reaction().emoji} ${reaction().count}`}
                    aria-pressed={props.activeEmoji.has(reaction().emoji) ? "true" : "false"}
                    onClick={() => select(reaction().emoji)}
                  >
                    <span class="chat-reaction-chip__emoji">{reaction().emoji}</span>
                    {reaction().count}
                  </button>
                )}
              </For>
            </div>
          </Show>
          <Show when={!props.disabled}>
            <Show
              when={custom()}
              fallback={
                <div
                  class="palette"
                  role="group"
                  aria-label={t("chat.reactions.quick")}
                  onKeyDown={movePaletteFocus}
                >
                  <For each={QUICK_REACTIONS}>
                    {(emoji) => (
                      <button
                        ref={(button) => {
                          paletteButtons[QUICK_REACTIONS.indexOf(emoji)] = button;
                        }}
                        class="emoji"
                        type="button"
                        aria-label={emoji}
                        aria-pressed={props.activeEmoji.has(emoji) ? "true" : "false"}
                        onClick={() => select(emoji)}
                      >
                        {emoji}
                      </button>
                    )}
                  </For>
                  <span class="divider" aria-hidden="true" />
                  <openclaw-tooltip prop:content={t("chat.reactions.more")}>
                    <button
                      ref={(button) => {
                        paletteButtons[QUICK_REACTIONS.length] = button;
                      }}
                      class="more"
                      type="button"
                      aria-label={t("chat.reactions.more")}
                      onClick={showCustom}
                    >
                      <Icon name="moreHorizontal" />
                    </button>
                  </openclaw-tooltip>
                </div>
              }
            >
              <div class="custom">
                <Errored
                  fallback={(error, resetError) => (
                    <>
                      {back()}
                      <LazyViewError error={error()} onRetry={resetError} />
                    </>
                  )}
                >
                  <Loading
                    fallback={
                      <>
                        {back()}
                        <LoadingState />
                      </>
                    }
                  >
                    <EmojiSearchPanel
                      inputRef={(input) => {
                        searchInput = input;
                        onSettled(focusPicker);
                      }}
                      query={query()}
                      onQueryChange={search}
                      onSelect={select}
                      isSelected={(emoji) => props.activeEmoji.has(emoji)}
                      defaults={SEARCH_DEFAULTS}
                      searchLabel={t("chat.reactions.search")}
                      gridLabel={t("chat.reactions.emoji")}
                      emptyLabel={t("chat.reactions.noMatches")}
                      onInputKeyDown={(event) => {
                        if (event.key === "Backspace" && !event.currentTarget.value) {
                          event.preventDefault();
                          showPalette();
                        }
                      }}
                      leading={back()}
                    />
                  </Loading>
                </Errored>
              </div>
            </Show>
          </Show>
        </Popover>
      </Show>
    </openclaw-message-reaction-picker>
  );
}
